<template>
  <view class="page" @touchmove.stop="dragMove" @touchend="dragEnd">
    <view class="stars"><view v-for="n in 24" :key="n" class="star" :style="starStyle(n)">✦</view></view>
    <view class="head"><view><text class="eyebrow">MY LITTLE DESK</text><text class="title">我的日记桌面</text></view><view class="new" @click="openToday">＋ 写今天</view></view>
    <text class="tip">长按文件夹可以自由移动，点击打开日记本</text>
    <scroll-view scroll-y class="scroll"><view v-for="group in monthGroups" :key="group.month" class="month-folder" :class="{folded: folded[group.month]}"><view class="month-head" @click="toggleMonth(group.month)"><view class="month-tab"></view><text class="month-name">{{group.label}}</text><text class="month-count">{{group.items.length}} 篇　{{folded[group.month]?'展开':'收起'}}⌄</text></view><view v-if="!folded[group.month]" class="month-body"><view v-for="item in group.items" :key="item.date" class="file" :style="fileStyle(item)" @touchstart.stop="dragStart(item,$event)" @click.stop="open(item.date)"><view class="file-paper"><text class="file-date">{{item.date.slice(8)}}</text><text class="file-mark">{{item.hasContent?'✦':'·'}}</text></view><text class="file-state">{{item.hasContent?'已记录':'空白页'}}</text></view><view class="new-file" @click.stop="openDatePicker">＋<text>新建日记</text></view></view></view><view v-if="!monthGroups.length" class="empty">还没有日记，先写下今天吧</view></scroll-view>
    <view v-if="showBook" class="mask" @click="closeBook"><view class="book" @click.stop><view v-if="!reading" class="cover"><text class="cover-label">MY DIARY</text><text class="cover-date">{{activeDate}}</text><text class="cover-note">今天也值得被记住</text><view class="open" @click="reading=true">翻开日记本</view></view><view v-else class="inside"><view class="bar"><text>{{activeDate}}</text><text @click="closeBook">合上</text></view><view class="quad-grid"><view class="quad" v-for="section in sections" :key="section.key" @click="editSection(section.key)"><text class="quad-title">{{section.title}}</text><text class="quad-preview">{{currentNote[section.key]||'点击写下今天的记录…'}}</text><text class="pen">✎</text></view></view><view class="save" @click="saveNote">{{saved?'已保存':'保存今天'}}</view></view></view></view>
    <view v-if="editingKey" class="mask" @click="editingKey=''" ><view class="editor" @click.stop><text class="edit-title">{{sectionTitle}}</text><textarea v-model="draftValue" auto-height maxlength="1000" placeholder="写下你想记住的事情…"/><view class="actions"><text @click="editingKey=''">取消</text><text class="done" @click="finishEdit">完成</text></view></view></view>
    <view v-if="showDatePicker" class="mask" @click="showDatePicker=false"><view class="editor" @click.stop><text class="edit-title">选择日记日期</text><picker mode="date" :value="pickerDate" @change="pickerDate=$event.detail.value"><view class="date-picker">{{pickerDate}}　点击选择</view></picker><view class="actions"><text @click="showDatePicker=false">取消</text><text class="done" @click="openPickedDate">打开</text></view></view></view>
  </view>
</template>
<script>
const KEY='fourPartDiaries'; const blank=()=>({food:'',timeline:'',thoughts:'',gratitude:''})
export default{data(){return{entries:[],folded:{},activeDate:'',currentNote:blank(),showBook:false,reading:false,editingKey:'',draftValue:'',saved:false,showDatePicker:false,pickerDate:this.formatDate(new Date()),dragging:null,suppressClick:false,sections:[{key:'food',title:'吃了什么'},{key:'timeline',title:'时间轴'},{key:'thoughts',title:'碎碎念'},{key:'gratitude',title:'感恩'}]}},computed:{monthGroups(){const map={};this.entries.forEach(item=>{const month=item.date.slice(0,7);if(!map[month])map[month]={month,label:month.replace('-',' 年 ')+' 月',items:[]};map[month].items.push(item)});return Object.values(map)},sectionTitle(){const s=this.sections.find(x=>x.key===this.editingKey);return s?s.title:''}},onShow(){this.loadEntries()},methods:{formatDate(d){return`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`},starStyle(n){return{left:(n*37)%100+'%',top:(n*53)%40+'%',opacity:.25+(n%4)*.15}},loadEntries(){const all=uni.getStorageSync(KEY)||{};this.entries=Object.keys(all).filter(k=>/^\d{4}-\d{2}-\d{2}$/.test(k)).sort().reverse().map(date=>({date,hasContent:Object.values(all[date]||{}).some(v=>v&&typeof v==='string'),x:all[date].x||0,y:all[date].y||0}))},toggleMonth(month){this.$set(this.folded,month,!this.folded[month])},fileStyle(item){return{transform:`translate(${item.x||0}rpx,${item.y||0}rpx)`}},dragStart(item,e){const t=e.touches&&e.touches[0];if(!t)return;this.dragging={item,startX:t.clientX,startY:t.clientY,originX:item.x||0,originY:item.y||0,moved:false}},dragMove(e){if(!this.dragging)return;const t=e.touches&&e.touches[0];if(!t)return;const dx=(t.clientX-this.dragging.startX)*2,dy=(t.clientY-this.dragging.startY)*2;if(Math.abs(dx)+Math.abs(dy)>12)this.dragging.moved=true;this.dragging.item.x=Math.max(-70,Math.min(160,this.dragging.originX+dx));this.dragging.item.y=Math.max(-20,Math.min(150,this.dragging.originY+dy))},dragEnd(){if(this.dragging&&this.dragging.moved){this.suppressClick=true;setTimeout(()=>{this.suppressClick=false},250);const all=uni.getStorageSync(KEY)||{};const item=this.dragging.item;all[item.date]={...(all[item.date]||{}),x:item.x,y:item.y};uni.setStorageSync(KEY,all);this.loadEntries()}this.dragging=null},openToday(){this.openEntry(this.formatDate(new Date()))},openDatePicker(){this.pickerDate=this.formatDate(new Date());this.showDatePicker=true},openPickedDate(){this.showDatePicker=false;this.openEntry(this.pickerDate)},openEntry(date){if(this.suppressClick)return;const all=uni.getStorageSync(KEY)||{};this.activeDate=date;this.currentNote={...blank(),...(all[date]||{})};this.showBook=true;this.reading=false;this.saved=false},closeBook(){this.showBook=false;this.editingKey='';this.loadEntries()},editSection(key){this.editingKey=key;this.draftValue=this.currentNote[key]||''},finishEdit(){this.currentNote[this.editingKey]=this.draftValue;this.editingKey='';this.saved=false},saveNote(){const all=uni.getStorageSync(KEY)||{};const old=all[this.activeDate]||{};all[this.activeDate]={...old,...this.currentNote,updatedAt:Date.now()};uni.setStorageSync(KEY,all);this.saved=true;this.loadEntries()}}}
</script>
<style lang="scss" scoped>
.page{min-height:100vh;background:linear-gradient(#102b5c 0,#246eaa 34%,#10284d 100%);padding:54rpx 28rpx 140rpx;box-sizing:border-box;position:relative;overflow:hidden}.stars{position:fixed;inset:0;pointer-events:none;z-index:0}.star{position:absolute;color:#bdeaff;font-size:18rpx;animation:twinkle 2.5s ease-in-out infinite}.head,.tip,.scroll{position:relative;z-index:1}.head{display:flex;justify-content:space-between;align-items:end;color:#fff}.eyebrow{display:block;font-size:20rpx;letter-spacing:4rpx;opacity:.7}.title{display:block;font-size:44rpx;font-weight:700;margin-top:10rpx}.new{background:#d8f5ff;color:#1b5c91;border-radius:28rpx;padding:14rpx 22rpx;font-size:24rpx;box-shadow:0 8rpx 18rpx #031e4566}.tip{display:block;color:#c8e9ff;font-size:24rpx;margin:20rpx 0 28rpx}.scroll{height:calc(100vh - 245rpx)}.month-folder{margin-bottom:26rpx;border-radius:28rpx;background:linear-gradient(145deg,#f0bd63,#d78a45);padding:18rpx 16rpx 20rpx;box-shadow:0 14rpx 28rpx #051d3b66;position:relative}.month-folder:before{content:'';position:absolute;left:20rpx;top:-16rpx;width:170rpx;height:28rpx;border-radius:16rpx 16rpx 0 0;background:#f6cc78}.month-head{height:70rpx;display:flex;align-items:center;justify-content:space-between;padding:0 12rpx;color:#603d29;position:relative}.month-name{font-size:34rpx;font-weight:700}.month-count{font-size:22rpx;opacity:.7}.month-body{min-height:250rpx;border-radius:20rpx;background:#e5a957aa;padding:24rpx 18rpx;display:grid;grid-template-columns:repeat(3,1fr);gap:22rpx 14rpx;position:relative}.file{text-align:center;position:relative;z-index:2;transition:transform .2s}.file:active{transform:scale(.95)}.file-paper{height:112rpx;background:#fff;border-radius:12rpx;box-shadow:0 8rpx 12rpx #75431f44;position:relative;overflow:hidden}.file-paper:before{content:'';position:absolute;left:0;right:0;top:0;height:22rpx;background:#dff3ff}.file-date{position:absolute;top:8rpx;left:0;right:0;text-align:center;color:#28638d;font-size:27rpx;font-weight:700;z-index:1}.file-mark{display:block;line-height:112rpx;font-size:44rpx;color:#f0c65c}.file-state{font-size:18rpx;color:#6e452e;margin-top:6rpx;display:block}.new-file{height:112rpx;border:2rpx dashed #fff8;border-radius:12rpx;color:#fff8;font-size:48rpx;text-align:center;line-height:72rpx}.new-file text{display:block;font-size:18rpx;line-height:10rpx}.folded .month-head{height:100rpx}.mask{position:fixed;inset:0;background:#061a36cc;z-index:20;display:flex;align-items:center;justify-content:center;padding:28rpx}.book{width:100%;min-height:850rpx;border-radius:22rpx;overflow:hidden;box-shadow:0 24rpx 70rpx #0008;animation:bookOpen .45s ease}.cover{min-height:850rpx;background:linear-gradient(145deg,#543d86,#a16ba8);color:#fff;display:flex;flex-direction:column;align-items:center;justify-content:center}.cover-label{font-size:22rpx;letter-spacing:8rpx;opacity:.8}.cover-date{font-size:62rpx;font-weight:700;margin:30rpx 0}.cover-note{font-size:24rpx;opacity:.8}.open,.save{background:#fff;color:#754f8e;border-radius:30rpx;padding:18rpx 30rpx;margin-top:44rpx;font-size:26rpx}.inside{padding:28rpx;background:repeating-linear-gradient(0deg,#f8f0df 0,#f8f0df 48rpx,#eadfcf 49rpx)}.bar{display:flex;justify-content:space-between;color:#624b3e;font-size:34rpx;font-weight:700}.bar text:last-child{font-size:23rpx;font-weight:400}.quad-grid{display:grid;grid-template-columns:1fr 1fr;gap:16rpx;margin-top:26rpx}.quad{min-height:270rpx;background:#fff9;padding:22rpx;border-radius:16rpx;box-shadow:inset 0 0 0 2rpx #decdb6;position:relative}.quad-title{display:block;font-size:28rpx;font-weight:700;color:#8f6049;border-bottom:2rpx solid #e7d5be;padding-bottom:12rpx}.quad-preview{display:block;color:#66574e;font-size:25rpx;line-height:1.65;margin-top:16rpx;word-break:break-all}.pen{position:absolute;right:16rpx;bottom:10rpx;color:#c28a68}.save{background:#8b5da0;color:#fff;width:max-content;margin:24rpx auto 0}.editor{width:100%;background:#fff8ee;border-radius:24rpx;padding:34rpx;box-sizing:border-box}.edit-title{display:block;font-size:36rpx;color:#694d3f;font-weight:700;margin-bottom:22rpx}.editor textarea{width:100%;min-height:300rpx;background:#fff;border-radius:16rpx;padding:22rpx;font-size:30rpx;box-sizing:border-box}.actions{display:flex;justify-content:flex-end;gap:28rpx;margin-top:26rpx;color:#986b53;font-size:28rpx}.done{background:#8b5da0;color:#fff;padding:14rpx 28rpx;border-radius:28rpx}.date-picker{background:#fff;padding:26rpx;border-radius:14rpx;color:#765846;font-size:30rpx}@keyframes bookOpen{0%{transform:perspective(900px) rotateY(-70deg);opacity:.3}100%{transform:rotateY(0);opacity:1}}@keyframes twinkle{0%,100%{opacity:.25;transform:scale(.8)}50%{opacity:1;transform:scale(1.3)}}.month-folder{transition:transform .25s,opacity .25s}.month-folder:active{transform:scale(.99)}
</style>



